head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > updateSuffix]<br/>서버의 suffix.txt 파일을 비동기 통신으로 호출하여 WebSquare 엔진의 suffix 설정값을 갱신합니다.",
    "validation" : [
        "서버의 suffix.txt 파일을 비동기 통신으로 호출하여 WebSquare 엔진의 suffix 설정값을 갱신해야 합니다.",
        "suffix 값은 리소스 URL 쿼리 문자열의 postfix 파라미터에 할당되어 브라우저 캐시 제어에 사용되어야 합니다.",
        "options(선택) 파라미터를 JSON 객체로 설정할 수 있어야 합니다.",
        "options.callback(선택) 파라미터로 suffix 갱신 완료 후 호출할 콜백 함수명 또는 함수 객체를 설정할 수 있어야 합니다.",        
        "suffix.txt 파일에 내용이 없으면 config.xml 의 engineCache/environment postfix 설정에 따라 postfix 값이 결정되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// suffix.txt 를 common_link 하위 테스트 파일로 리다이렉트 (프로젝트 공통 /websquare/suffix.txt 영향 없음)
scwin.suffixFileMap = {
    "string"  : "/sample/common_link/p_updateSuffix_string.txt",
    "json"    : "/sample/common_link/p_updateSuffix_json.txt",
    "empty"   : "/sample/common_link/p_updateSuffix_empty.txt"
};

scwin.redirectSuffixXHR = function (targetUri) {
    if (!targetUri) return null;
    var originalOpen = XMLHttpRequest.prototype.open;
    XMLHttpRequest.prototype.open = function (method, url) {
        if (typeof url === "string" && url.indexOf("suffix.txt") > -1 && url.indexOf("/sample/common_link/") < 0) {
            var qIdx = url.indexOf("?");
            arguments[1] = targetUri + (qIdx > -1 ? url.substring(qIdx) : "");
        }
        return originalOpen.apply(this, arguments);
    };
    return { restore : function () { XMLHttpRequest.prototype.open = originalOpen; } };
};

// WebSquare.suffix 상태 요약
scwin.getSuffixState = function () {
    if (typeof WebSquare === "undefined" || typeof WebSquare.suffix === "undefined") {
        return "undefined (WebSquare.suffix 미설정)";
    }
    var s = WebSquare.suffix;
    if (s === null) return "null";
    if (typeof s === "string") return "string : '" + s + "'";
    if (typeof s === "object") {
        try { return "object : " + JSON.stringify(s); } catch (e) { return "object"; }
    }
    return typeof s;
};

// bootloader.generateSuffixPostfix : 지정 uri 에 적용될 postfix 문자열
scwin.getGeneratedPostfix = function (uri) {
    try {
        if (WebSquare && WebSquare.BootLoader && typeof WebSquare.BootLoader.generateSuffixPostfix === "function") {
            return WebSquare.BootLoader.generateSuffixPostfix(uri);
        }
    } catch (e) {}
    return "";
};

// suffix.txt 내용 없을 때 사용되는 config.xml fallback postfix 값 조회
// bootloader.enginePostfix   = config.xml /WebSquare/engineCache/@postfix (예: "month" → 실제 값)
// bootloader.resourcePostfix = config.xml /WebSquare/environment/@postfix (예: "day" → 실제 값)
// ※ environment/@cache="nocache" 이면 resourcePostfix 는 설정되지 않고 getRandomPostfix 로 분기됨
//    → 이 경우에도 config 원시값(예: "day") 을 generatePostfix() 로 평가하여 "설정값이 평가되면 이런 값" 을 보여줌
scwin.getFallbackPostfix = function () {
    var result = {
        engineCacheRaw     : "",  // config 원시값 (예: "month")
        engineCacheApplied : "",  // 실제 적용값 (runtime)
        envRaw             : "",  // config 원시값 (예: "day")
        envEvaluated       : "",  // generatePostfix 평가값 (예: "2026_04_21")
        envApplied         : "",  // 실제 적용값 (nocache 면 빈 값)
        envCacheMode       : ""   // "nocache" / 그 외
    };
    try {
        var b = WebSquare && WebSquare.BootLoader;
        var core = WebSquare && WebSquare.core;
        if (core && typeof core.getConfiguration === "function") {
            result.engineCacheRaw = core.getConfiguration("/WebSquare/engineCache/@postfix") || "";
            result.envRaw         = core.getConfiguration("/WebSquare/environment/@postfix") || "";
            result.envCacheMode   = core.getConfiguration("/WebSquare/environment/@cache") || "";
        }
        if (b) {
            result.engineCacheApplied = (typeof b.enginePostfix !== "undefined" ? b.enginePostfix : "");
            result.envApplied         = (typeof b.resourcePostfix !== "undefined" ? b.resourcePostfix : "");
            if (result.envRaw && typeof b.generatePostfix === "function") {
                result.envEvaluated = b.generatePostfix(result.envRaw);
            }
        }
    } catch (e) {}
    return result;
};

// 콜백 함수 (par_callback 이 'string' 일 때 사용)
scwin.updateSuffix_callback = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("options.callback (함수명 문자열) 호출됨");
};



scwin.btn_updateSuffix_onclick = async function () {
    var suffixKey = par_suffixFile.getValue();
    var callbackType = par_callback.getValue();
    var redirectTarget = scwin.suffixFileMap[suffixKey] || "";

    // suffix.txt 리다이렉트 설정
    var handle = scwin.redirectSuffixXHR(redirectTarget);

    // 이전 시나리오에서 설정된 WebSquare.suffix 초기화 (엔진은 빈 응답 시 기존 값 유지하므로 테스트 격리 위해 리셋)
    try { delete WebSquare.suffix; } catch (e) { WebSquare.suffix = undefined; }

    // options 구성
    var options;
    if (callbackType === "func") {
        options = {
            callback : function () {
                wf_body_bottom.getObj("scwin").setReturnValue("options.callback (함수 객체) 호출됨");
            }
        };
    } else if (callbackType === "string") {
        options = { callback : "scwin.updateSuffix_callback" };
    } else {
        options = undefined;
    }

    // updateSuffix 호출
    var ret = $p.updateSuffix(options);

    // Promise 또는 대기 후 결과 확인
    var onDone = function () {
        wf_body_bottom.getObj("scwin").setReturnValue("WebSquare.suffix : " + scwin.getSuffixState());
        var generated = scwin.getGeneratedPostfix("/langpack/ko.js");
        wf_body_bottom.getObj("scwin").setReturnValue("generateSuffixPostfix('/langpack/ko.js') : '" + generated + "'");
        if (!generated) {
            // suffix 값 없을 때 → config.xml engineCache/environment fallback 사용
            var fb = scwin.getFallbackPostfix();
            wf_body_bottom.getObj("scwin").setReturnValue("config.xml engineCache/@postfix : '" + fb.engineCacheRaw + "' : '" + fb.engineCacheApplied);
            if (fb.envCacheMode === "nocache") {
                wf_body_bottom.getObj("scwin").setReturnValue("config.xml environment/@postfix : '" + fb.envRaw + "' : '" + fb.envEvaluated);
            } else {
                wf_body_bottom.getObj("scwin").setReturnValue("config.xml environment/@postfix : '" + fb.envRaw + "' : '" + fb.envEvaluated + "' / 실제 적용값 : '" + fb.envApplied + "' (일반 리소스 URL 에 적용)");
            }
        }
        if (handle) handle.restore();
    };
    if (ret && typeof ret.then === "function") {
        ret.then(onDone, function (err) {
            wf_body_bottom.getObj("scwin").setReturnValue("reject : " + err);
            if (handle) handle.restore();
        });
    } else {
        setTimeout(onDone, 700);
    }
};
